BEGIN;

CREATE TABLE "Projects" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" varchar(200) NOT NULL,
    "Description" varchar(1000) NOT NULL
);

CREATE TABLE "TaskItems" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ProjectId" integer NOT NULL REFERENCES "Projects" ("Id") ON DELETE CASCADE,
    "Title" varchar(200) NOT NULL,
    "Description" varchar(1000) NOT NULL,
    "DueDate" timestamp without time zone,
    "IsCompleted" boolean NOT NULL
);

CREATE INDEX "IX_TaskItems_ProjectId" ON "TaskItems" ("ProjectId");

INSERT INTO "Projects" ("Id", "Name", "Description") VALUES
    (1, 'Website Redesign', 'Redesign the company website with a modern look and improved user experience.'),
    (2, 'Mobile App Development', 'Develop a cross-platform mobile application for customer engagement.'),
    (3, 'Database Migration', 'Migrate legacy database to the new cloud infrastructure.');

INSERT INTO "TaskItems" ("Id", "ProjectId", "Title", "Description", "DueDate", "IsCompleted") VALUES
    (1, 1, 'Create wireframes', 'Design initial wireframes for the homepage and key landing pages.', '2026-01-09', true),
    (2, 1, 'Implement responsive design', 'Ensure the website works well on all device sizes.', '2026-01-16', false),
    (3, 1, 'Set up analytics', 'Integrate Google Analytics and set up conversion tracking.', '2026-01-23', false),
    (4, 2, 'Define app requirements', 'Document all functional and non-functional requirements.', '2026-01-07', true),
    (5, 2, 'Design UI mockups', 'Create detailed UI mockups for all screens.', '2026-01-12', true),
    (6, 2, 'Implement authentication', 'Build user authentication and authorization module.', '2026-01-22', false),
    (7, 3, 'Analyze current schema', 'Document the existing database schema and relationships.', '2026-01-05', true),
    (8, 3, 'Create migration scripts', 'Write scripts to migrate data to the new database.', '2026-01-17', false);

SELECT setval(pg_get_serial_sequence('"Projects"', 'Id'), (SELECT max("Id") FROM "Projects"));
SELECT setval(pg_get_serial_sequence('"TaskItems"', 'Id'), (SELECT max("Id") FROM "TaskItems"));

COMMIT;
